package com.careflow.hospital.notifications;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.sql.ResultSet;import java.time.Instant;import java.util.*;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/notifications")public class NotificationController{private final JdbcTemplate jdbc;public NotificationController(JdbcTemplate j){jdbc=j;}public record Create(@NotNull UUID userId,@NotBlank String subject,@NotBlank@Size(max=1000)String body){}public record View(UUID notificationId,String channel,String subject,String body,String status,Instant createdAt){}
 @GetMapping public List<View> list(Authentication a){return jdbc.query("select notification_id,channel,subject,body,status,created_at from notification where user_id=? order by created_at desc",(rs,n)->view(rs),user(a));}
 @PostMapping@PreAuthorize("hasAnyRole('ADMIN','STAFF')")ResponseEntity<View> create(@Valid@RequestBody Create r){UUID id=UUID.randomUUID();jdbc.update("insert into notification(notification_id,user_id,channel,subject,body,status) values (?,?,?,?,?,'SENT')",id,r.userId(),"IN_APP",r.subject(),r.body());return ResponseEntity.status(HttpStatus.CREATED).body(jdbc.queryForObject("select notification_id,channel,subject,body,status,created_at from notification where notification_id=?",(rs,n)->view(rs),id));}
 @PostMapping("/{id}/read") public View read(Authentication a,@PathVariable UUID id){int changed=jdbc.update("update notification set status='READ',read_at=now() where notification_id=? and user_id=?",id,user(a));if(changed==0)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND);return jdbc.queryForObject("select notification_id,channel,subject,body,status,created_at from notification where notification_id=?",(rs,n)->view(rs),id);}
 private View view(ResultSet r)throws java.sql.SQLException{return new View(r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getTimestamp(6).toInstant());}private UUID user(Authentication a){return UUID.fromString(a.getName());}}
